def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    high_spenders = 0
    mid_spenders = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 75:
                    high_spenders += 1
                elif bid >= 40:
                    mid_spenders += 1

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 25.0))
        return float(min(budget, 8.0))

    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = 1.0 - max(0.0, min(1.0, supply_ratio))

    pressure = 0.0
    if prev_bids:
        top_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
        pressure = max(top_prev * 0.55, avg_prev)
    else:
        top_prev = 0.0
        avg_prev = 0.0
        pressure = 45.0

    need = 0.0
    if hp <= 2:
        need += 40.0
    elif hp <= 4:
        need += 22.0
    elif hp <= 6:
        need += 10.0

    if no_water_days >= 2:
        need += 35.0
    elif no_water_days >= 1:
        need += 18.0

    if day >= 8:
        need += 8.0

    contest_bonus = high_spenders * 6.0 + mid_spenders * 2.5

    target = 28.0 + scarcity * 22.0 + need + contest_bonus

    if pressure >= 80:
        if hp >= 7 and no_water_days == 0 and supply <= 18:
            target = min(target, 36.0)
        else:
            target = max(target, min(pressure + 2.0, 96.0))
    elif pressure >= 50:
        target = max(target, min(pressure + 1.5, 72.0))
    else:
        target = max(target, 52.0 if scarcity > 0.5 else 38.0)

    if hp >= 8 and no_water_days == 0 and supply >= 22:
        target -= 10.0

    if budget < 120:
        target = min(target, budget * 0.55 + 8.0)
    elif budget < 220:
        target = min(target, budget * 0.65)

    if hp <= 2 or no_water_days >= 2:
        target = max(target, 88.0 if budget >= 88.0 else budget)

    target = max(0.0, min(float(budget), float(target)))
    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((oid, o))

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from traces for immediate reaction
    yesterday_bids = []
    yesterday_hp_after = []
    for _, o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass
        hp_after = prev.get('hp_after', None)
        if hp_after is not None:
            try:
                yesterday_hp_after.append(int(hp_after))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = (sum(yesterday_bids) / len(yesterday_bids)) if yesterday_bids else 0.0

    # Supply pressure: with higher supply, we can bid less; with lower supply, increase to avoid losing.
    # supply is 15-25; map to [0..1]
    if MAX_SUPPLY > MIN_SUPPLY:
        pressure = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        pressure = 0.5
    pressure = max(0.0, min(1.0, pressure))

    # Base bid: mid-band between 0.45 and 0.75 of salary depending on supply pressure.
    # If supply is low (pressure small), bid higher.
    base = DAILY_SALARY * (0.75 - 0.30 * pressure)

    # React to yesterday's high bidding: if someone else pushed near salary, we must not be too low.
    # Yesterday meta shows Cindy/Alex around 82-84 (~0.92*salary), so target slightly below that.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # If our hp is low, bid closer to the high band.
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.90
        else:
            target = DAILY_SALARY * 0.78
    else:
        # If bids were generally low, we can bid around avg to secure water.
        if avg_prev_bid > 0:
            target = max(base, min(budget, avg_prev_bid + 5.0))
        else:
            target = base

    # Ensure we don't overspend early: cap based on remaining days in episode (10 days total).
    # With no_water_days increasing, we should spend more.
    remaining_days = max(1, 10 - day)
    urgency = min(1.0, (no_water_days + (2 if hp <= 2 else 0)) / 4.0)
    cap = DAILY_SALARY * (0.55 + 0.35 * urgency)

    bid = min(budget, target, cap)

    # If we are at critical hp, force a higher bid to avoid elimination.
    if hp <= 1:
        bid = min(budget, DAILY_SALARY * 0.95)

    # Also if supply is extremely low relative to requirement, bid higher.
    # Use integer indexing safety not needed here, but keep logic consistent.
    if supply < float(WATER_REQ):
        bid = min(budget, DAILY_SALARY * 0.95)

    # Final sanity: bid must be non-negative.
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    current_day = day_context['day']
    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    max_yesterday_bid = 0
    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)

    supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    adjusted_supply_factor = 1 - supply_factor
    supply_adjustment = (DAILY_SALARY * 0.1) * adjusted_supply_factor

    calculated_bid = 0.0

    if not yesterday_bids or max_yesterday_bid < DAILY_SALARY * 0.4:
        calculated_bid = DAILY_SALARY * 0.55 + supply_adjustment
        if num_alive_opponents == 1 and max_yesterday_bid < DAILY_SALARY * 0.3:
            calculated_bid = max(max_yesterday_bid + 1, DAILY_SALARY * 0.2)
    else:
        if my_status['hp'] <= 3:
            calculated_bid = max(max_yesterday_bid + 5, DAILY_SALARY * 0.85)
        elif my_status['hp'] <= 6:
            calculated_bid = max(max_yesterday_bid + 3, DAILY_SALARY * 0.75)
        else:
            calculated_bid = max(max_yesterday_bid + 1, DAILY_SALARY * 0.65)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        if my_status['hp'] <= 5:
            calculated_bid = max(calculated_bid, DAILY_SALARY * 0.9)
        elif my_status['hp'] <= 8:
            calculated_bid = max(calculated_bid, DAILY_SALARY * 0.8)

    final_bid = min(my_status['budget'], calculated_bid)

    if final_bid < 1.0 and my_status['budget'] >= 1.0:
        final_bid = 1.0
    elif my_status['budget'] == 0:
        final_bid = 0.0

    return max(0.0, final_bid)

